import { buildSpeakerReport, speakerFramesPerReport, speakerReportDuration, speakerReportId } from '../protocol/speaker'
import type { OutputReport, OutputState } from '../protocol/output'
import { getSpeakerTestFrames } from '../audio/speakerTestTone'
import { parseSpeakerSbc } from '../audio/parseSpeakerSbc'
import { abortable } from '../utils/abortable'

/** @internal */
export interface SpeakerSession {
  signal: AbortSignal
  send: (report: OutputReport, cancellation?: AbortSignal, onSubmitted?: () => void) => Promise<void>
  control: (enabled: boolean, bluetoothPollInterval?: number) => Promise<void>
}

interface Playback {
  abort: AbortController
  sessionSignal: AbortSignal
  task: Promise<void>
  enabled: boolean
  bufferDurationMs: number
  bluetoothPollInterval: number
  framesPerReport: number
}

export interface SpeakerPlaybackOptions {
  /** Estimated controller audio reserve, 16–2048 ms in 16 ms steps. Default 64.
   * Larger values are experimental: WebHID cannot query the actual FIFO capacity.
   */
  bufferDurationMs?: number
  /** DS4 Bluetooth input-report interval field (integer 0–16). Default 0.
   * Increasing it can reduce inbound traffic competing with audio writes.
   */
  bluetoothPollInterval?: number
  /** SBC frames per HID report: 1 (0x12), 2 (0x14), or 4 (0x17, default). */
  framesPerReport?: 1 | 2 | 4
}

export interface SpeakerPlaybackDiagnostics {
  framesPerReport: number
  reportId: number
  audioPerReportMs: number
  bitpool: number
  frameBytes: number
  bitrateKbps: number
  bluetoothPollInterval: number
  bufferDurationMs: number
  reportCount: number
  audioMs: number
  elapsedMs: number
  averageGapMs: number
  maxGapMs: number
  averageWriteMs: number
  maxWriteMs: number
  maxQueueMs: number
}

// Refill reports are spaced rather than flooding the HID queue;
// even short packets contain at least 4 ms of audio.
const speakerRefillInterval = 4

/** Experimental Bluetooth-only playback on the built-in mono speaker. */
export default class DualShock4Speaker {
  private playback?: Playback
  private lastDiagnostics?: SpeakerPlaybackDiagnostics

  /** @internal */
  constructor (private readonly getSession: (audioReportId: number) => SpeakerSession) {}

  /** True while playing or waiting for the final mute command. */
  get playing (): boolean { return this.playback !== undefined }

  /** Host-side timing of the last playback. Does not measure Bluetooth delivery or the actual FIFO. */
  get diagnostics (): SpeakerPlaybackDiagnostics | undefined {
    return this.lastDiagnostics ? { ...this.lastDiagnostics } : undefined
  }

  /** Audio settings to preserve when ordinary effects change. @internal */
  get outputState (): OutputState['speaker'] {
    const playback = this.playback
    return playback && !playback.sessionSignal.aborted ? {
      enabled: playback.enabled, volume: 0x40,
      bluetoothPollInterval: playback.enabled ? playback.bluetoothPollInterval : 0
    } : undefined
  }

  /**
   * Plays an 800 ms, low-amplitude 1 kHz test signal on the internal speaker.
   * Requires Bluetooth exposing control 0x11 and the selected audio report.
   * Resolves after playback or stop(); rejects on unsupported devices, concurrent
   * tests, device loss, or HID write errors. Physical audibility is not verified.
   */
  async test (options: SpeakerPlaybackOptions = {}): Promise<void> {
    return this.start(getSpeakerTestFrames(), options)
  }

  /**
   * Plays raw SBC data: 32 kHz joint stereo, SNR allocation, 8 subbands,
   * 16 blocks and bitpool 24 or 48 (61/109 bytes/frame). Data is copied and validated
   * before playback; invalid or truncated files reject with RangeError.
   * Up to three silent frames pad the last HID packet. Shares test()/stop()
   * lifecycle and exclusivity. Volume is fixed; prepare audio at a low level.
   */
  async playSbc (data: ArrayBuffer | Uint8Array, options: SpeakerPlaybackOptions = {}): Promise<void> {
    return this.start(parseSpeakerSbc(data), options)
  }

  private async start (frames: readonly Uint8Array[], options: SpeakerPlaybackOptions): Promise<void> {
    if (this.playback) throw new DOMException('Speaker playback already running.', 'InvalidStateError')
    const bufferDurationMs = options.bufferDurationMs ?? 64
    const bluetoothPollInterval = options.bluetoothPollInterval ?? 0
    const framesPerReport = options.framesPerReport ?? speakerFramesPerReport
    const audioReportId = speakerReportId(framesPerReport, frames[0].length)
    if (!Number.isInteger(bluetoothPollInterval) || bluetoothPollInterval < 0 || bluetoothPollInterval > 16) {
      throw new RangeError('bluetoothPollInterval must be an integer from 0 to 16.')
    }
    if (!Number.isInteger(bufferDurationMs) || bufferDurationMs < 16 || bufferDurationMs > 2048 || bufferDurationMs % speakerReportDuration) {
      throw new RangeError('bufferDurationMs must be 16–2048 ms in 16 ms steps.')
    }
    const session = this.getSession(audioReportId)
    session.signal.throwIfAborted()
    const playback: Playback = { abort: new AbortController(), sessionSignal: session.signal, task: Promise.resolve(), enabled: false, bufferDurationMs, bluetoothPollInterval, framesPerReport }
    this.lastDiagnostics = undefined
    this.playback = playback
    // Start on a microtask so stop() always sees the full playback promise.
    playback.task = Promise.resolve().then(() => this.play(session, playback, frames))
    return playback.task
  }

  /** Stops playback and waits for its mute command. Safe to call when idle. */
  async stop (): Promise<void> {
    const playback = this.playback
    if (!playback) return
    playback.abort.abort(new DOMException('Speaker playback stopped.', 'AbortError'))
    return playback.task
  }

  private async play (session: SpeakerSession, playback: Playback, frames: readonly Uint8Array[]): Promise<void> {
    const signal = AbortSignal.any([session.signal, playback.abort.signal])
    const began = performance.now()
    const framesPerReport = playback.framesPerReport
    const reportDuration = 4 * framesPerReport
    const diagnostics: SpeakerPlaybackDiagnostics = {
      framesPerReport, reportId: speakerReportId(framesPerReport, frames[0].length), audioPerReportMs: reportDuration,
      bitpool: frames[0][2], frameBytes: frames[0].length, bitrateKbps: frames[0].length * 2,
      bluetoothPollInterval: playback.bluetoothPollInterval,
      bufferDurationMs: playback.bufferDurationMs, reportCount: 0, audioMs: 0,
      elapsedMs: 0, averageGapMs: 0, maxGapMs: 0, averageWriteMs: 0, maxWriteMs: 0, maxQueueMs: 0
    }
    let previousSubmission: number | undefined
    let totalGaps = 0
    let totalWrites = 0
    let armed = false
    try {
      signal.throwIfAborted()
      playback.enabled = true
      armed = true // A failed write may still have reached the controller.
      await session.control(true, playback.bluetoothPollInterval)
      let bufferedUntil = performance.now()
      for (let index = 0; index < frames.length; index += framesPerReport) {
        signal.throwIfAborted()
        const queued = performance.now()
        let submitted = queued
        await session.send(buildSpeakerReport(index, frames.slice(index, index + framesPerReport), playback.bluetoothPollInterval), signal, () => {
          // Measure after competing effects leave the shared output queue.
          submitted = performance.now()
        })
        // HID completion latency is part of the audio period, not an additional
        // delay after it. Only rebase when the estimated reserve is exhausted.
        const completed = performance.now()
        diagnostics.reportCount++
        if (previousSubmission !== undefined) {
          const gap = submitted - previousSubmission
          totalGaps += gap
          diagnostics.maxGapMs = Math.max(diagnostics.maxGapMs, gap)
        }
        previousSubmission = submitted
        const writeMs = completed - submitted
        totalWrites += writeMs
        diagnostics.maxWriteMs = Math.max(diagnostics.maxWriteMs, writeMs)
        diagnostics.maxQueueMs = Math.max(diagnostics.maxQueueMs, submitted - queued)
        bufferedUntil = Math.max(bufferedUntil, completed) + reportDuration
        const last = index + framesPerReport >= frames.length
        const deadline = last
          ? bufferedUntil // Let the final buffered samples play before muting.
          : Math.max(bufferedUntil - playback.bufferDurationMs + reportDuration, submitted + speakerRefillInterval)
        await waitForPlayback(deadline - performance.now(), signal)
      }
    } catch (error) {
      session.signal.throwIfAborted()
      if (error !== playback.abort.signal.reason) throw error
    } finally {
      playback.enabled = false
      try {
        if (armed && !session.signal.aborted) await session.control(false)
      } finally {
        diagnostics.elapsedMs = performance.now() - began
        diagnostics.audioMs = diagnostics.reportCount * reportDuration
        diagnostics.averageGapMs = diagnostics.reportCount > 1 ? totalGaps / (diagnostics.reportCount - 1) : 0
        diagnostics.averageWriteMs = diagnostics.reportCount ? totalWrites / diagnostics.reportCount : 0
        this.lastDiagnostics = diagnostics
        if (this.playback === playback) this.playback = undefined
      }
    }
  }
}

async function waitForPlayback (milliseconds: number, signal: AbortSignal): Promise<void> {
  signal.throwIfAborted()
  if (milliseconds <= 0) return
  let timer: ReturnType<typeof setTimeout> | undefined
  try {
    await abortable(new Promise<void>(resolve => { timer = setTimeout(resolve, Math.max(0, Math.ceil(milliseconds))) }), signal)
  } finally {
    clearTimeout(timer)
  }
}
