/** @module @internal */
import type { OutputReport } from './output'
import { crc32 } from '../utils/crc32'

export const speakerFrameSize = 109
export const speakerFramesPerReport = 4
export const speakerReportDuration = 16

export function speakerReportId (framesPerReport: number, frameSize = speakerFrameSize): number {
  if (![1, 2, 4].includes(framesPerReport) || ![61, 109].includes(frameSize)) {
    throw new RangeError('Speaker reports require one, two, or four equal 61- or 109-byte SBC frames.')
  }
  // Preserve the established frame-count/report-ID pairing. Fitting encoded
  // bytes into a smaller report does not establish that the pad accepts it.
  return framesPerReport === 1 ? 0x12 : framesPerReport === 2 ? 0x14 : 0x17
}

/** One, two, or four SBC frames addressed to the internal speaker. */
export function buildSpeakerReport (frameNumber: number, frames: readonly Uint8Array[], bluetoothPollInterval = 0): OutputReport {
  const frameSize = frames[0]?.length
  const reportId = speakerReportId(frames.length, frameSize)
  if (frames.some(frame => frame.length !== frameSize)) {
    throw new RangeError('Speaker report frames must have equal sizes.')
  }
  // Includes the synthetic Bluetooth transaction byte used only by CRC.
  const report = new Uint8Array(reportId === 0x12 ? 143 : reportId === 0x14 ? 271 : 463)
  const crcOffset = report.length - 4
  // Low bits select the inbound Bluetooth report interval. Keep the same value
  // in control/effect reports so audio does not reset it to the fastest rate.
  report.set([0xA2, reportId, 0x40 | bluetoothPollInterval, 0xA0])
  new DataView(report.buffer).setUint16(4, frameNumber, true)
  report[6] = 0x02 // Internal speaker; 0x24 would select headphones.
  frames.forEach((frame, index) => report.set(frame, 7 + index * frameSize))
  new DataView(report.buffer).setUint32(crcOffset, crc32(report.subarray(0, crcOffset)), true)
  return { reportId, data: report.slice(2), raw: report.buffer }
}

export function supportsSpeakerReports (collections: readonly HIDCollectionInfo[], audioReportId = 0x17): boolean {
  const ids = new Set<number>()
  const visit = (items: readonly HIDCollectionInfo[]) => {
    for (const collection of items) {
      collection.outputReports?.forEach(report => {
        if (report.reportId !== undefined) ids.add(report.reportId)
      })
      visit(collection.children ?? [])
    }
  }
  visit(collections)
  return ids.has(0x11) && ids.has(audioReportId)
}
