/** @module @internal */
import { speakerFramesPerReport } from '../protocol/speaker'
import { getSpeakerTestFrames } from './speakerTestTone'

/** Validate and snapshot raw SBC before enabling the controller's audio mode. */
export function parseSpeakerSbc (data: ArrayBuffer | Uint8Array): Uint8Array[] {
  const bytes = data instanceof Uint8Array ? new Uint8Array(data) : new Uint8Array(data).slice()
  const bitpool = bytes[2]
  if (bytes.length < 4 || ![24, 48].includes(bitpool)) {
    throw new RangeError('SBC data must use bitpool 24 or 48.')
  }
  const speakerFrameSize = 13 + 2 * bitpool
  if (bytes.length % speakerFrameSize !== 0) {
    throw new RangeError(`SBC data must contain complete ${speakerFrameSize}-byte frames.`)
  }
  const frames: Uint8Array[] = []
  for (let offset = 0; offset < bytes.length; offset += speakerFrameSize) {
    const frame = bytes.subarray(offset, offset + speakerFrameSize)
    // 32 kHz, 16 blocks, joint stereo, SNR allocation, 8 subbands; fixed bitpool.
    if (frame[0] !== 0x9C || frame[1] !== 0x7F || frame[2] !== bitpool) {
      throw new RangeError(`Unsupported SBC format at byte ${offset}; expected 32 kHz joint stereo, SNR, 8 subbands, 16 blocks, constant bitpool ${bitpool}.`)
    }
    if (!hasValidHeaderCrc(frame)) throw new RangeError(`Invalid SBC header CRC at byte ${offset}.`)
    frames.push(frame)
  }
  if (frames.length % speakerFramesPerReport) {
    // Native libsbc-encoded zero PCM with matching bitpool and header CRC.
    const silence = bitpool === 48 ? getSpeakerTestFrames().at(-1)! : new Uint8Array(61).fill(0x55)
    if (bitpool === 24) silence.set([0x9C, 0x7F, 24, 0x4C, 0, 0, 0, 0, 0, 0, 0, 0, 0])
    while (frames.length % speakerFramesPerReport) frames.push(silence)
  }
  return frames
}

function hasValidHeaderCrc (frame: Uint8Array): boolean {
  // SBC CRC-8 covers bytes 1/2, the joint-stereo mask and scale factors.
  // For this fixed format that is 88 bits; byte 3 holds the checksum itself.
  let crc = 0x0F
  for (const byte of [frame[1], frame[2], ...frame.subarray(4, 13)]) {
    crc ^= byte
    for (let bit = 0; bit < 8; bit++) crc = ((crc << 1) ^ (crc & 0x80 ? 0x1D : 0)) & 0xFF
  }
  return crc === frame[3]
}
