<template>
  <div>
    <div v-for="(controller, i) in controllers" :key="i">
      <h2>
        Controller #{{i}} ({{controller.state.interface.toUpperCase()}},
        Battery: {{controller.state.batteryCapacity === null ? 'unknown' : `${controller.state.batteryCapacity}%`}}
        [{{controller.state.batteryStatus}}])
      </h2>
      <div class="params">
        <h4>Lightbar Color</h4>
        <label>R: </label><input type="range" min="0" max="255" v-model="controller.lightbar.r"> ({{controller.lightbar.r}})<br>
        <label>G: </label><input type="range" min="0" max="255" v-model="controller.lightbar.g"> ({{controller.lightbar.g}})<br>
        <label>B: </label><input type="range" min="0" max="255" v-model="controller.lightbar.b"> ({{controller.lightbar.b}})
        <h4>Rumble</h4>
        <label>Weak: </label><input type="range" min="0" max="255" v-model="controller.rumble.light">  ({{controller.rumble.light}})<br>
        <label>Strong: </label><input type="range" min="0" max="255" v-model="controller.rumble.heavy">  ({{controller.rumble.heavy}})
        <h4>Built-in Speaker (experimental)</h4>
        <p>Bluetooth only. Play a quiet test tone or the 5.3-second audio sample on the controller's mono speaker.</p>
        <p>
          <label :for="`speaker-bitrate-${i}`">Sample bitrate: </label>
          <select :id="`speaker-bitrate-${i}`" v-model.number="speakerBitpool" :disabled="controller.speaker.playing || sampleLoading[i]">
            <option :value="48">218 kbit/s (original)</option>
            <option :value="24">122 kbit/s (experimental)</option>
          </select>
        </p>
        <p>
          <label :for="`speaker-buffer-${i}`">Audio send-ahead: </label>
          <select :id="`speaker-buffer-${i}`" v-model.number="speakerBufferMs" :disabled="controller.speaker.playing || sampleLoading[i]">
            <option :value="64">64 ms</option>
            <option :value="256">256 ms</option>
            <option :value="1024">1024 ms (1 second)</option>
            <option :value="2048">2048 ms (2 seconds)</option>
          </select>
        </p>
        <p>
          <label :for="`speaker-poll-${i}`">Bluetooth input interval: </label>
          <select :id="`speaker-poll-${i}`" v-model.number="speakerPollInterval" :disabled="controller.speaker.playing || sampleLoading[i]">
            <option :value="0">0 (previous setting)</option>
            <option :value="4">4</option>
            <option :value="8">8</option>
            <option :value="16">16</option>
          </select>
        </p>
        <button :disabled="controller.state.interface !== 'bt' || controller.speaker.playing || sampleLoading[i]" @click="testSpeaker(controller, i)">
          Test speaker
        </button>
        <button :disabled="controller.state.interface !== 'bt' || controller.speaker.playing || sampleLoading[i]" @click="playSample(controller, i)">
          {{sampleLoading[i] && !packetProbeRunning[i] ? 'Loading sample…' : 'Play sample'}}
        </button>
        <button :disabled="controller.state.interface !== 'bt' || controller.speaker.playing || sampleLoading[i]" @click="comparePacketSizes(controller, i)">
          {{packetProbeRunning[i] ? 'Comparing packets…' : 'Compare packet sizes'}}
        </button>
        <button :disabled="!controller.speaker.playing && !sampleLoading[i]" @click="stopSpeaker(controller, i)">Stop</button>
        <p role="status" aria-live="polite">{{speakerStatus[i]}}</p>
        <details v-if="speakerDiagnostics[i]" open>
          <summary>Playback diagnostics (timing-v5)</summary>
          <pre>{{speakerDiagnostics[i]}}</pre>
          <p>Host timing only; the controller's actual buffer capacity and Bluetooth delivery are unknown.</p>
        </details>
        <p v-if="controller.state.interface !== 'bt'">Connect the controller via Bluetooth to test its speaker.</p>
      </div>
      <div class="buttons">
        <h3>Buttons</h3>
        <div class="btn" v-for="(button, btnKey) in controller.state.buttons" :key="btnKey" :style="{ opacity: button ? 1 : 0.5 }">
          <b class="name">{{btnKey}}</b><br>
          {{button ? '1.00' : '0.00'}}
        </div>
      </div>
      <div class="analogs">
        <h3>Analogs</h3>
        <div class="analog" v-for="(analog, anaKey) in controller.state.axes" :key="anaKey" :style="{ opacity: 0.5 + Math.min(0.5, Math.abs(analog) * .5) }">
          <b class="name">{{anaKey}}</b><br>
          {{analog.toFixed(2)}}
        </div>
      </div>
      <div class="touchpad">
        <h3>Touchpad</h3>
        <div v-if="!controller.state.touchpad.touches.length">
          No touches detected.
        </div>
        <div v-else v-for="touch in controller.state.touchpad.touches" :key="touch.touchId">
          <b>Touch #{{touch.touchId}}:</b> {{touch.x}}, {{touch.y}}
        </div>
      </div>
    </div>
    <br><br>
    <button v-if="hidSupported" @click="addController">Connect Controller</button>
    <div v-else>
      WebHID is not available in this browser or page context.<br>
      Use a supported desktop Chromium browser over HTTPS or localhost, and
      <a href="https://developer.mozilla.org/docs/Web/API/WebHID_API#browser_compatibility">check current browser compatibility</a>.
    </div>
  </div>
</template>
<script>
import { reactive } from 'vue'
import { DualShock4 } from '../src'
import sampleUrl from 'url:./both.sbc'
import lowSampleUrl from 'url:./both-low.sbc'

const sampleRequests = new WeakMap()

export default {
  name: 'ControllerDemo',
  data () {
    return {
      controllers: [],
      speakerStatus: [],
      sampleLoading: [],
      packetProbeRunning: [],
      speakerBufferMs: 1024,
      speakerBitpool: 48,
      speakerPollInterval: 8,
      speakerDiagnostics: []
    }
  },
  methods: {
    async comparePacketSizes (controller, index) {
      if (sampleRequests.has(controller) || controller.speaker.playing) return
      const device = controller.device
      const request = new AbortController()
      sampleRequests.set(controller, request)
      this.sampleLoading[index] = true
      this.packetProbeRunning[index] = true
      this.speakerDiagnostics[index] = ''
      this.speakerStatus[index] = 'Loading packet comparison…'
      const results = []
      const bluetoothPollInterval = this.speakerPollInterval
      try {
        const response = await fetch(this.speakerBitpool === 24 ? lowSampleUrl : sampleUrl, { signal: request.signal })
        if (!response.ok) throw new Error(`Could not load sample (HTTP ${response.status}).`)
        // 24 complete frames, 96 ms of source audio per case: short enough to
        // measure a slow transport without streaming the full file three times.
        const file = new Uint8Array(await response.arrayBuffer())
        const bytes = file.slice(0, 24 * (13 + 2 * file[2]))
        for (const framesPerReport of [1, 2, 4]) {
          request.signal.throwIfAborted()
          if (controller.device !== device || !device?.opened) throw new Error('Controller disconnected during comparison.')
          this.speakerStatus[index] = `Comparing ${framesPerReport} frame(s) per packet…`
          const playback = controller.speaker.playSbc(bytes, { framesPerReport, bluetoothPollInterval, bufferDurationMs: 64 })
          const started = controller.speaker.playing
          try {
            await playback
            request.signal.throwIfAborted()
            results.push(controller.speaker.diagnostics)
          } catch (error) {
            request.signal.throwIfAborted()
            if (started || error.name !== 'NotSupportedError') throw error
            results.push({ framesPerReport, error: error.message })
          }
          this.speakerDiagnostics[index] = this.formatDiagnostics(results)
        }
        this.speakerStatus[index] = 'Packet comparison complete. Compare averageWriteMs with audioPerReportMs.'
      } catch (error) {
        if (!request.signal.aborted) this.speakerStatus[index] = `Packet comparison failed: ${error.message}`
      } finally {
        if (sampleRequests.get(controller) === request) {
          sampleRequests.delete(controller)
          this.sampleLoading[index] = false
          this.packetProbeRunning[index] = false
        }
      }
    },
    async playSample (controller, index) {
      if (sampleRequests.has(controller) || controller.speaker.playing) return
      const device = controller.device
      const request = new AbortController()
      sampleRequests.set(controller, request)
      this.sampleLoading[index] = true
      this.speakerDiagnostics[index] = ''
      this.speakerStatus[index] = 'Loading sample…'
      let playbackStarted = false
      try {
        const response = await fetch(this.speakerBitpool === 24 ? lowSampleUrl : sampleUrl, { signal: request.signal })
        if (!response.ok) throw new Error(`Could not load sample (HTTP ${response.status}).`)
        const data = await response.arrayBuffer()
        request.signal.throwIfAborted()
        if (controller.device !== device || !device?.opened) throw new Error('Controller disconnected while loading the sample.')
        const playback = controller.speaker.playSbc(data, { bufferDurationMs: this.speakerBufferMs, bluetoothPollInterval: this.speakerPollInterval })
        playbackStarted = controller.speaker.playing
        this.sampleLoading[index] = false
        this.speakerStatus[index] = 'Playing sample…'
        await playback
        if (this.speakerStatus[index] === 'Playing sample…') {
          this.speakerStatus[index] = 'Sample sent. Confirm by listening to the controller.'
        }
      } catch (error) {
        if (!request.signal.aborted) this.speakerStatus[index] = `Sample playback failed: ${error.message}`
      } finally {
        if (playbackStarted) this.updateSpeakerDiagnostics(controller, index)
        if (sampleRequests.get(controller) === request) {
          sampleRequests.delete(controller)
          this.sampleLoading[index] = false
        }
      }
    },
    async testSpeaker (controller, index) {
      this.speakerDiagnostics[index] = ''
      this.speakerStatus[index] = 'Playing test tone…'
      let playbackStarted = false
      try {
        const playback = controller.speaker.test({ bufferDurationMs: this.speakerBufferMs, bluetoothPollInterval: this.speakerPollInterval })
        playbackStarted = controller.speaker.playing
        await playback
        if (this.speakerStatus[index] === 'Playing test tone…') {
          this.speakerStatus[index] = 'Test signal sent. Confirm by listening to the controller.'
        }
      } catch (error) {
        this.speakerStatus[index] = `Speaker test failed: ${error.message}`
      } finally {
        if (playbackStarted) this.updateSpeakerDiagnostics(controller, index)
      }
    },
    updateSpeakerDiagnostics (controller, index) {
      const stats = controller.speaker.diagnostics
      if (!stats) return
      this.speakerDiagnostics[index] = this.formatDiagnostics(stats)
    },
    formatDiagnostics (stats) {
      return JSON.stringify(stats, (_key, value) =>
        typeof value === 'number' ? Math.round(value * 100) / 100 : value, 2)
    },
    async stopSpeaker (controller, index) {
      sampleRequests.get(controller)?.abort()
      sampleRequests.delete(controller)
      this.sampleLoading[index] = false
      this.packetProbeRunning[index] = false
      this.speakerStatus[index] = 'Stopping speaker test…'
      try {
        await controller.speaker.stop()
        this.speakerStatus[index] = 'Speaker test stopped.'
      } catch (error) {
        this.speakerStatus[index] = `Could not stop the speaker test: ${error.message}`
      }
    },
    stopSpeakers () {
      this.controllers.forEach((controller, index) => {
        if (controller.speaker.playing || sampleRequests.has(controller)) void this.stopSpeaker(controller, index)
      })
    },
    handleVisibilityChange () {
      if (document.hidden) this.stopSpeakers()
    },
    async addController () {
      const rawController = new DualShock4()
      // HID callbacks capture the original controller in its constructor.
      // Make their state target reactive before wrapping the public instance.
      rawController.state = reactive(rawController.state)
      const controller = reactive(rawController)
      rawController.addEventListener('disconnect', () => {
        sampleRequests.get(controller)?.abort()
        sampleRequests.delete(controller)
        const index = this.controllers.indexOf(controller)
        if (index !== -1) {
          this.sampleLoading[index] = false
          this.packetProbeRunning[index] = false
          this.speakerStatus[index] = 'Controller disconnected.'
        }
        // Disconnect replaces state through the original instance as well.
        rawController.state = reactive(rawController.state)
        this.controllers = [...this.controllers]
      })
      if (await controller.connect()) {
        this.controllers.push(controller)
      }
    }
  },
  mounted () {
    document.addEventListener('visibilitychange', this.handleVisibilityChange)
    window.addEventListener('pagehide', this.stopSpeakers)
  },
  beforeUnmount () {
    document.removeEventListener('visibilitychange', this.handleVisibilityChange)
    window.removeEventListener('pagehide', this.stopSpeakers)
    this.stopSpeakers()
  },
  computed: {
    hidSupported () {
      return !!(window.navigator.hid && window.navigator.hid.requestDevice)
    }
  }
}
</script>
